 async planAction(op,extra={}){try{await this._hass.callWS({type:'finance_tracker/plan_edit',op,data:{month:this.month,...extra}});await this.refresh();}catch(e){await window.FTDialog.alert('Finanzplanung',e.message||String(e));}}
