 monthGrid(chosen=[],start=this.month,count=18){let a=[];let d=new Date(+start.slice(0,4),+start.slice(5)-1,1);for(let i=0;i<count;i++){const x=new Date(d.getFullYear(),d.getMonth()+i,1);const m=x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0');a.push(`<label style="display:inline-flex;gap:5px;align-items:center;padding:6px 9px;border:1px solid #344657;border-radius:9px"><input type="checkbox" name="months" value="${m}" ${chosen.includes(m)?'checked':''}>${this.esc(this.label(m))}</label>`);}return `<div style="display:flex;flex-wrap:wrap;gap:6px">${a.join('')}</div>`;}
